export interface Subtitle {
  id: string;
  start: number;
  end: number;
  text: string;
}

export interface SubtitleStyle {
  font: string;
  fontSize: number;
  fontWeight: string;
  color: string;
  backgroundColor: string;
  backgroundOpacity: number;
  positionY: number; // Percentage from top
  positionX: number; // Percentage from left
  strokeWidth: number;
  strokeColor: string;
}

export interface MediaData {
  mediaId: string;
  base64: string;
  mimeType: string;
  name: string;
}

export function formatTime(seconds: number): string {
  const hrs = Math.floor(seconds / 3600);
  const mins = Math.floor((seconds % 3600) / 60);
  const secs = Math.floor(seconds % 60);
  const ms = Math.floor((seconds % 1) * 1000);

  return `${hrs.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')},${ms.toString().padStart(3, '0')}`;
}

export function generateSRT(subtitles: { start: number; end: number; text: string }[]): string {
  return subtitles
    .map((sub, i) => {
      return `${i + 1}\
${formatTime(sub.start)} --> ${formatTime(sub.end)}\
${sub.text}\
`;
    })
    .join('\
');
}

export function sanitizeFilename(name: string, ext: string): string {
  const clean = name.replace(/[^a-zA-Z0-9_\-]/g, '_').slice(0, 30);
  return `${clean || 'subtitles'}.${ext}`;
}

/**
 * Splits text into lines if it exceeds a certain length
 */
export function wrapText(ctx: CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D, text: string, maxWidth: number): string[] {
  const words = text.split(' ');
  const lines: string[] = [];
  let currentLine = words[0];

  for (let i = 1; i < words.length; i++) {
    const word = words[i];
    const width = ctx.measureText(currentLine + ' ' + word).width;
    if (width < maxWidth) {
      currentLine += ' ' + word;
    } else {
      lines.push(currentLine);
      currentLine = word;
    }
  }
  lines.push(currentLine);
  return lines;
}

import React from 'react';
import { Subtitle } from '../types';

interface SubtitleItemProps {
  subtitle: Subtitle;
  isActive: boolean;
  onUpdate: (id: string, updates: Partial<Subtitle>) => void;
  onDelete: (id: string) => void;
  onSelect: (time: number) => void;
  onSetTime: (id: string, field: 'start' | 'end') => void;
}

export const SubtitleItem: React.FC<SubtitleItemProps> = ({
  subtitle,
  isActive,
  onUpdate,
  onDelete,
  onSelect,
  onSetTime,
}) => {
  return (
    <div 
      onClick={() => onSelect(subtitle.start)}
      className={`group flex flex-col gap-2 p-3 rounded-xl border transition-all cursor-pointer ${
        isActive 
          ? 'bg-[#1a1a1a] border-[#969696] ring-1 ring-[#969696]/20' 
          : 'bg-transparent border-[#595959] hover:border-[#7a7a7a]'
      }`}
    >
      <div className="flex items-center justify-between gap-2">
        <div className="flex items-center gap-1.5" onClick={e => e.stopPropagation()}>
          <div className="flex items-center gap-1 bg-white/5 rounded-md px-1.5 py-0.5 border border-white/5">
            <input
              type="number"
              step="0.01"
              value={subtitle.start}
              onChange={(e) => onUpdate(subtitle.id, { start: parseFloat(e.target.value) || 0 })}
              className="bg-transparent text-[10px] font-medium text-white/80 w-12 outline-none hover:text-white transition-colors"
            />
            <button 
              onClick={() => onSetTime(subtitle.id, 'start')}
              title="Set to current playhead"
              className="material-symbols-outlined text-[14px] text-white/30 hover:text-white transition-colors"
            >
              schedule
            </button>
          </div>

          <span className="text-[10px] text-white/20">→</span>

          <div className="flex items-center gap-1 bg-white/5 rounded-md px-1.5 py-0.5 border border-white/5">
            <input
              type="number"
              step="0.01"
              value={subtitle.end}
              onChange={(e) => onUpdate(subtitle.id, { end: parseFloat(e.target.value) || 0 })}
              className="bg-transparent text-[10px] font-medium text-white/80 w-12 outline-none hover:text-white transition-colors"
            />
            <button 
              onClick={() => onSetTime(subtitle.id, 'end')}
              title="Set to current playhead"
              className="material-symbols-outlined text-[14px] text-white/30 hover:text-white transition-colors"
            >
              schedule
            </button>
          </div>
        </div>
        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
          <button 
            onClick={(e) => {
              e.stopPropagation();
              onDelete(subtitle.id);
            }}
            className="material-symbols-outlined text-[16px] text-red-400/60 hover:text-red-400"
          >
            delete
          </button>
        </div>
      </div>
      <textarea
        value={subtitle.text}
        onChange={(e) => onUpdate(subtitle.id, { text: e.target.value })}
        onClick={e => e.stopPropagation()}
        rows={2}
        className="bg-transparent text-[12px] font-medium text-white w-full resize-none outline-none placeholder:text-white/20 leading-snug"
        placeholder="Enter text..."
      />
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Flow } from 'flow-sdk';
import { 
  Input, Output, Conversion, ALL_FORMATS, BlobSource, Mp4OutputFormat, BufferTarget
} from 'mediabunny';
import { registerAc3Decoder, registerAc3Encoder } from '@mediabunny/ac3';
import { Subtitle, SubtitleStyle, MediaData } from './types';
import { generateSRT, sanitizeFilename, wrapText } from './utils';
import { SubtitleItem } from './components/SubtitleItem';
import { SearchableDropdown } from './components/SearchableDropdown';
import { FONT_OPTIONS } from './constants';

// Primitives from Design System
const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

const PillButton: React.FC<{
  icon?: React.ReactNode; children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; onClick?: () => void;
  disabled?: boolean;
}> = ({ icon, children, variant = 'filled', onClick, disabled }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

const RangeSlider: React.FC<{
  label: string; value: number; min: number; max: number;
  step?: number; formatValue?: (val: number) => string;
  onChange: (val: number) => void;
}> = ({ label, value, min, max, step = 1, formatValue = (v) => String(v), onChange }) => (
  <div className="flex flex-col gap-2 pt-2 pb-[5px] w-full">
    <div className="flex items-center justify-between px-2 select-none">
      <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">{label}</span>
      <span className="text-[11px] font-medium text-[#c7c9cd] tracking-[0.1px]">{formatValue(value)}</span>
    </div>
    <div className="px-2 w-full flex items-center h-2">
      <input type="range" min={min} max={max} step={step} value={value}
        onChange={(e) => onChange(Number(e.target.value))} />
    </div>
  </div>
);

const DragNumberField: React.FC<{
  label: string; value: number; min?: number; max?: number;
  step?: number; suffix?: string; onChange: (val: number) => void; className?: string;
}> = ({ label, value, min = -99, max = 99, step = 0.1, suffix = 's', onChange, className = '' }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState(String(value));
  const inputRef = useRef<HTMLInputElement>(null);
  const dragRef = useRef<{ startY: number; startVal: number; moved: boolean } | null>(null);

  const commitEdit = (raw: string) => {
    const parsed = parseFloat(raw);
    if (!isNaN(parsed)) onChange(Math.min(max, Math.max(min, Math.round(parsed / step) * step)));
    setIsEditing(false);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (isEditing) return;
    e.preventDefault();
    dragRef.current = { startY: e.clientY, startVal: value, moved: false };
    const handleMouseMove = (ev: MouseEvent) => {
      if (!dragRef.current) return;
      if (Math.abs(ev.clientY - dragRef.current.startY) > 3) dragRef.current.moved = true;
      if (dragRef.current.moved) {
        const delta = dragRef.current.startY - ev.clientY;
        const newVal = dragRef.current.startVal + (delta * step * 0.2);
        onChange(Math.min(max, Math.max(min, newVal)));
        document.body.style.cursor = 'ns-resize';
      }
    };
    const handleMouseUp = () => {
      const wasDrag = dragRef.current?.moved;
      dragRef.current = null;
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      if (!wasDrag) {
        setEditValue(String(value.toFixed(2)));
        setIsEditing(true);
        setTimeout(() => inputRef.current?.select(), 0);
      }
    };
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  };

  return (
    <div className={`border border-[#595959] hover:border-[#7a7a7a] rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none transition-colors ${isEditing ? '' : 'cursor-ns-resize'} ${className}`}
      onMouseDown={handleMouseDown}>
      <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
      <div className="flex items-center justify-between">
        {isEditing ? (
          <input ref={inputRef} type="text" value={editValue}
            onChange={(e) => setEditValue(e.target.value)}
            onKeyDown={(e) => { if (e.key === 'Enter') commitEdit(editValue); if (e.key === 'Escape') setIsEditing(false); }}
            onBlur={() => commitEdit(editValue)}
            className="bg-transparent text-[11px] font-medium text-white tracking-[0.1px] outline-none w-full border-none p-0 m-0" autoFocus />
        ) : (
          <>
            <span className="text-[11px] font-medium text-white tracking-[0.1px] cursor-text">{value.toFixed(2)}{suffix}</span>
            <div className="flex flex-col items-center mr-1.5 -gap-px text-white/40">
              <svg width="10" height="6" viewBox="0 0 10 6" fill="none"><path d="M5 0L9 5H1L5 0Z" fill="currentColor"/></svg>
              <svg width="10" height="6" viewBox="0 0 10 6" fill="none"><path d="M5 6L1 1H9L5 6Z" fill="currentColor"/></svg>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

function useOnClickOutside(ref: React.RefObject<HTMLElement | null>, handler: (e: MouseEvent | TouchEvent) => void) {
  useEffect(() => {
    const listener = (event: MouseEvent | TouchEvent) => {
      if (!ref.current || ref.current.contains(event.target as Node)) return;
      handler(event);
    };
    document.addEventListener('mousedown', listener);
    document.addEventListener('touchstart', listener);
    return () => { 
      document.removeEventListener('mousedown', listener); 
      document.removeEventListener('touchstart', listener); 
    };
  }, [ref, handler]);
}

const FieldDropdown: React.FC<{
  label: string; value: string; options: string[];
  onChange: (val: string) => void; className?: string;
}> = ({ label, value, options, onChange, className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  useOnClickOutside(ref, () => setIsOpen(false));

  return (
    <div ref={ref} className={`relative ${className}`}>
      <button type="button" onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none focus:outline-none">
        <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white tracking-[0.1px] truncate pr-2">{value}</span>
          <span className={`material-symbols-outlined text-[16px] text-[rgba(218,220,224,0.5)] mr-1 transition-transform ${isOpen ? 'rotate-180' : ''}`}>keyboard_arrow_down</span>
        </div>
      </button>
      {isOpen && (
        <div className="absolute z-50 bottom-[calc(100%+4px)] left-0 w-full bg-[#0e0e0e] border border-[#595959] rounded-xl overflow-hidden shadow-xl backdrop-blur-md animate-dropdown origin-bottom">
          <div className="max-h-48 overflow-y-auto dark-scrollbar">
            {options.map((opt) => (
              <button key={opt} type="button"
                className={`w-full text-left px-2.5 py-2 text-[11px] font-medium tracking-[0.1px] hover:bg-[#1a1a1a] transition-colors ${value === opt ? 'bg-[#1a1a1a] text-white' : 'text-[rgba(218,220,224,0.9)]'}`}
                onClick={() => { onChange(opt); setIsOpen(false); }}>
                {opt}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default function SubtitleTool() {
  // State
  const [media, setMedia] = useState<MediaData | null>(null);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [subtitles, setSubtitles] = useState<Subtitle[]>([]);
  const [style, setStyle] = useState<SubtitleStyle>({
    font: 'Google Sans',
    fontSize: 28,
    fontWeight: 'Bold',
    color: '#ffffff',
    backgroundColor: '#000000',
    backgroundOpacity: 0.5,
    positionY: 85,
    positionX: 50,
    strokeWidth: 0,
    strokeColor: '#000000',
  });
  const [isTranscribing, setIsTranscribing] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [progress, setProgress] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [shiftOffset, setShiftOffset] = useState(0);

  // Refs
  const videoRef = useRef<HTMLVideoElement>(null);

  // Initialize Encoders and Custom Fonts
  useEffect(() => {
    const init = async () => {
      registerAc3Decoder();
      registerAc3Encoder();
    };
    init();

    const fontLink = document.createElement('link');
    fontLink.rel = 'stylesheet';
    const familiesToLoad = FONT_OPTIONS.slice(0, 30).map(f => f.replace(/ /g, '+')).join('|');
    fontLink.href = `https://fonts.googleapis.com/css2?family=${familiesToLoad}:wght@400;700;900&display=swap`;
    document.head.appendChild(fontLink);

    const id = 'flow-design-system-css';
    if (!document.getElementById(id)) {
      const styleEl = document.createElement('style');
      styleEl.id = id;
      styleEl.textContent = `
        input[type=range] { -webkit-appearance: none; appearance: none; background: transparent; width: 100%; cursor: pointer; padding: 8px 0; }
        input[type=range]::-webkit-slider-runnable-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }
        input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); margin-top: -5.5px; cursor: grab; }
        input[type=range]::-webkit-slider-thumb:active { cursor: grabbing; }
        .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #595959 transparent; }
        .dark-scrollbar::-webkit-scrollbar { width: 6px; }
        .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
        @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to { opacity: 1; transform: scale(1) translateY(0); } }
        .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }
        html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; font-family: 'Google Sans Text', -apple-system, sans-serif; overflow: hidden; }
      `;
      document.head.appendChild(styleEl);
    }
  }, []);

  // Update current time for preview
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    const onTimeUpdate = () => setCurrentTime(video.currentTime);
    video.addEventListener('timeupdate', onTimeUpdate);
    return () => video.removeEventListener('timeupdate', onTimeUpdate);
  }, [videoUrl]);

  // Handle media selection
  const handleSelectVideo = async () => {
    try {
      setError(null);
      const selected = await Flow.media.select({ filter: 'video' });

      if (videoUrl) {
        URL.revokeObjectURL(videoUrl);
      }

      setMedia(selected);
      const bytes = Uint8Array.from(atob(selected.base64), c => c.charCodeAt(0));
      const blob = new Blob([bytes], { type: selected.mimeType });
      const url = URL.createObjectURL(blob);
      setVideoUrl(url);
      setSubtitles([]);
    } catch (err: any) {
      if (err.message !== 'User cancelled selection') {
        setError(err.message || 'Failed to select video');
      }
    }
  };

  // Auto-transcription
  const handleAutoSubtitle = async () => {
    if (!media) return;
    setIsTranscribing(true);
    setError(null);
    try {
      const prompt = `Transcribe this English video with EXTREMELY PRECISE word-level timestamps. 
      Important constraints:
      1. Alignment: The 'start' time MUST be the exact moment the very first syllable of the segment is audible. 
      2. No padding: Do not add any leading or trailing silence buffer to the start/end times.
      3. Short Segments: If someone speaks quickly, split into segments of max 6-8 words for better readability.
      4. JSON Only: Return ONLY a valid JSON array of objects.

      Each object must have: 
      - "start": float (seconds, 2 decimal precision)
      - "end": float (seconds, 2 decimal precision)
      - "text": string (the transcription segment)

      Example: [{"start": 0.45, "end": 2.12, "text": "This is a precisely timed subtitle."}]`;

      const response = await Flow.generate.text(prompt, {
        videos: [{ base64: media.base64, mimeType: media.mimeType }]
      });

      const jsonMatch = response.text.match(/\[.*\]/s);
      if (jsonMatch) {
        const parsed: any[] = JSON.parse(jsonMatch[0]);
        const mapped: Subtitle[] = parsed.map((item, i) => ({
          id: `sub-${i}-${Date.now()}`,
          start: typeof item.start === 'number' ? Math.max(0, item.start) : 0,
          end: typeof item.end === 'number' ? item.end : 0,
          text: item.text || '',
        }));
        setSubtitles(mapped.sort((a, b) => a.start - b.start));
      } else {
        throw new Error('Could not parse transcription output');
      }
    } catch (err: any) {
      setError('Transcription failed. Please try again.');
      console.error(err);
    } finally {
      setIsTranscribing(false);
    }
  };

  // Global Time Shift
  const applyTimeShift = () => {
    if (shiftOffset === 0) return;
    setSubtitles(prev => prev.map(s => ({
      ...s,
      start: Math.max(0, s.start + shiftOffset),
      end: Math.max(0, s.end + shiftOffset),
    })));
    setShiftOffset(0);
  };

  // Subtitle management
  const updateSubtitle = (id: string, updates: Partial<Subtitle>) => {
    setSubtitles(prev => prev.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  const setTimeToPlayhead = (id: string, field: 'start' | 'end') => {
    if (!videoRef.current) return;
    const time = parseFloat(videoRef.current.currentTime.toFixed(3));
    updateSubtitle(id, { [field]: time });
  };

  const deleteSubtitle = (id: string) => {
    setSubtitles(prev => prev.filter(s => s.id !== id));
  };

  const addSubtitle = () => {
    const last = subtitles[subtitles.length - 1];
    const start = last ? last.end + 0.1 : (videoRef.current?.currentTime || 0);
    const newSub: Subtitle = {
      id: `sub-${Date.now()}`,
      start: parseFloat(start.toFixed(3)),
      end: parseFloat((start + 2.0).toFixed(3)),
      text: '',
    };
    setSubtitles(prev => [...prev, newSub].sort((a, b) => a.start - b.start));
  };

  // Export SRT
  const handleExportSRT = async () => {
    if (subtitles.length === 0) return;
    const srt = generateSRT(subtitles);
    const base64 = btoa(unescape(encodeURIComponent(srt)));
    const filename = sanitizeFilename(media?.name || 'subtitles', 'srt');

    await Flow.download({
      base64,
      mimeType: 'text/plain',
      filename,
    });
  };

  // Burn-in export
  const handleBurnInExport = async () => {
    if (!media || subtitles.length === 0) return;
    setIsExporting(true);
    setProgress(0);
    setError(null);

    try {
      const bytes = Uint8Array.from(atob(media.base64), c => c.charCodeAt(0));
      const blob = new Blob([bytes], { type: media.mimeType });

      const input = new Input({ source: new BlobSource(blob), formats: ALL_FORMATS });
      const output = new Output({
        format: new Mp4OutputFormat({ fastStart: 'in-memory' }),
        target: new BufferTarget(),
      });

      const videoTrack = await input.getPrimaryVideoTrack();
      const outWidth = videoTrack?.displayWidth || 1280;
      const outHeight = videoTrack?.displayHeight || 720;

      let ctx: OffscreenCanvasRenderingContext2D | null = null;

      const conversion = await Conversion.init({
        input,
        output,
        video: {
          width: outWidth,
          height: outHeight,
          fit: 'fill',
          process: (sample) => {
            if (!ctx) {
              const canvas = new OffscreenCanvas(outWidth, outHeight);
              ctx = canvas.getContext('2d')!;
            }

            sample.draw(ctx, 0, 0, outWidth, outHeight);

            const time = sample.timestamp;
            const sub = subtitles.find(s => time >= s.start && time <= s.end);

            if (sub && sub.text.trim()) {
              const weightMap: Record<string, string> = { 'Regular': '400', 'Bold': '700', 'Black': '900' };
              const fontStr = `${weightMap[style.fontWeight] || '700'} ${style.fontSize}px "${style.font}", sans-serif`;

              ctx.font = fontStr;
              ctx.textBaseline = 'middle';
              ctx.textAlign = 'center';

              const maxWidth = outWidth * 0.8;
              const lines = wrapText(ctx, sub.text, maxWidth);
              const lineHeight = style.fontSize * 1.2;
              const totalHeight = lines.length * lineHeight;

              const baseY = (outHeight * style.positionY) / 100;
              const baseX = (outWidth * style.positionX) / 100;
              const bgPadding = 10;

              if (style.backgroundOpacity > 0) {
                ctx.fillStyle = style.backgroundColor;
                ctx.globalAlpha = style.backgroundOpacity;

                let maxLineWidth = 0;
                lines.forEach(l => {
                  const w = ctx!.measureText(l).width;
                  if (w > maxLineWidth) maxLineWidth = w;
                });

                ctx.fillRect(
                  baseX - (maxLineWidth / 2) - bgPadding,
                  baseY - (totalHeight / 2) - bgPadding,
                  maxLineWidth + bgPadding * 2,
                  totalHeight + bgPadding * 2
                );
                ctx.globalAlpha = 1.0;
              }

              ctx.fillStyle = style.color;
              if (style.strokeWidth > 0) {
                ctx.strokeStyle = style.strokeColor;
                ctx.lineWidth = style.strokeWidth;
                ctx.lineJoin = 'round';
              }

              lines.forEach((line, i) => {
                const y = baseY - (totalHeight / 2) + (i * lineHeight) + (lineHeight / 2);
                if (style.strokeWidth > 0) {
                  ctx.strokeText(line, baseX, y);
                }
                ctx.fillText(line, baseX, y);
              });
            }

            return ctx.canvas;
          }
        }
      });

      conversion.onProgress = (p) => setProgress(p);
      await conversion.execute();

      const buffer = output.target.buffer!;
      const resultBlob = new Blob([buffer], { type: 'video/mp4' });
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = (reader.result as string).split(',')[1];
        await Flow.save({ base64, mimeType: 'video/mp4', name: `Subtitled_${media.name}.mp4` });
        setIsExporting(false);
      };
      reader.readAsDataURL(resultBlob);

    } catch (err: any) {
      setError('Export failed: ' + err.message);
      setIsExporting(false);
    }
  };

  const activeSubtitle = subtitles.find(s => currentTime >= s.start && currentTime <= s.end);

  const getWeightClass = (w: string) => {
    if (w === 'Regular') return 'font-normal';
    if (w === 'Bold') return 'font-bold';
    if (w === 'Black') return 'font-black';
    return 'font-bold';
  };

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] text-white overflow-hidden">
      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0 h-full">
        <div className="flex-1 relative flex items-center justify-center p-4 min-h-0 bg-[#0a0a0a]">
          {!videoUrl ? (
            <div className="flex flex-col items-center gap-4">
              <div className="w-16 h-16 rounded-full bg-white/5 flex items-center justify-center">
                <span className="material-symbols-outlined text-[32px] text-white/40">video_library</span>
              </div>
              <PillButton variant="solid" onClick={handleSelectVideo} icon={<span className="material-symbols-outlined text-[18px]">add</span>}>
                Select Video to Start
              </PillButton>
            </div>
          ) : (
            <div className="relative w-full h-full flex items-center justify-center">
              <div className="relative max-w-full max-h-full aspect-video bg-black rounded-2xl overflow-hidden group shadow-2xl">
                <video 
                  ref={videoRef}
                  src={videoUrl}
                  className="w-full h-full object-contain"
                  controls
                />

                {activeSubtitle && (
                  <div 
                    className="absolute pointer-events-none px-4 py-2 transition-all z-10"
                    style={{
                      top: `${style.positionY}%`,
                      left: `${style.positionX}%`,
                      transform: 'translate(-50%, -50%)',
                      textAlign: 'center',
                      maxWidth: '80%',
                    }}
                  >
                    <div 
                      className={`rounded-lg inline-block whitespace-pre-wrap px-3 py-1 ${getWeightClass(style.fontWeight)}`}
                      style={{
                        backgroundColor: style.backgroundColor,
                        color: style.color,
                        opacity: style.backgroundOpacity === 0 ? 1 : style.backgroundOpacity + 0.4,
                        background: style.backgroundOpacity === 0 ? 'transparent' : undefined,
                        fontSize: `${style.fontSize}px`,
                        fontFamily: `"${style.font}", sans-serif`,
                        lineHeight: '1.2',
                        WebkitTextStroke: style.strokeWidth > 0 ? `${style.strokeWidth / 2}px ${style.strokeColor}` : 'none',
                        textShadow: style.strokeWidth > 0 ? `0 0 ${style.strokeWidth}px ${style.strokeColor}` : 'none'
                      }}
                    >
                      {activeSubtitle.text}
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>

        {/* Bottom Editor Strip */}
        {videoUrl && (
          <div className="h-[320px] flex-shrink-0 border-t border-[rgba(218,220,224,0.15)] flex flex-col bg-[#0e0e0e] z-20">
            <div className="flex items-center justify-between px-6 py-3 border-b border-white/5 bg-white/[0.02]">
              <div className="flex items-center gap-3">
                <SectionLabel>Subtitle Editor</SectionLabel>
                <div className="h-4 w-px bg-white/10" />
                <span className="text-[10px] text-white/40 uppercase tracking-widest tabular-nums">
                  {currentTime.toFixed(2)}s
                </span>
              </div>
              <button 
                onClick={addSubtitle}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-white/5 hover:bg-white/10 text-[11px] font-medium text-white transition-all active:scale-95"
              >
                <span className="material-symbols-outlined text-[16px]">add</span>
                Add Segment
              </button>
            </div>
            <div className="flex-1 overflow-y-auto px-6 py-4 flex gap-4 flex-wrap content-start dark-scrollbar">
              {subtitles.length === 0 && !isTranscribing && (
                <div className="w-full flex flex-col items-center justify-center h-full gap-2 text-white/40">
                  <span className="text-[12px]">No subtitles yet. Use "Auto Subtitle" to generate them.</span>
                </div>
              )}
              {isTranscribing && (
                <div className="w-full flex flex-col items-center justify-center h-full gap-4">
                  <div className="w-8 h-8 border-2 border-white/20 border-t-white rounded-full animate-spin" />
                  <span className="text-[12px] font-medium animate-pulse">Syncing speech with AI...</span>
                </div>
              )}
              {subtitles.map(sub => (
                <div key={sub.id} className="w-[280px] flex-shrink-0">
                  <SubtitleItem 
                    subtitle={sub}
                    isActive={activeSubtitle?.id === sub.id}
                    onUpdate={updateSubtitle}
                    onDelete={deleteSubtitle}
                    onSetTime={setTimeToPlayhead}
                    onSelect={(t) => {
                      if (videoRef.current) {
                        videoRef.current.currentTime = t;
                        videoRef.current.play();
                      }
                    }}
                  />
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Right Sidebar Panel */}
      <div className="w-[300px] flex-shrink-0 border-l border-[rgba(218,220,224,0.15)] flex flex-col justify-between py-3 px-[10px] bg-[#0e0e0e] h-full overflow-hidden">
        <div className="flex flex-col gap-5 overflow-y-auto dark-scrollbar pr-1 flex-1">

          <div className="flex flex-col gap-2">
            <SectionLabel>Media Control</SectionLabel>
            <PillButton 
              variant="filled"
              onClick={handleSelectVideo}
              disabled={isExporting || isTranscribing}
              icon={<span className="material-symbols-outlined text-[18px]">video_library</span>}
            >
              Replace Video
            </PillButton>
            <PillButton 
              variant={isTranscribing ? 'outline' : 'filled'}
              onClick={handleAutoSubtitle}
              disabled={!media || isTranscribing || isExporting}
              icon={<span className="material-symbols-outlined text-[18px]">auto_fix_high</span>}
            >
              {isTranscribing ? 'Transcribing...' : 'Auto Subtitle AI'}
            </PillButton>
          </div>

          <div className="flex flex-col gap-2">
            <SectionLabel>Timing Adjustment</SectionLabel>
            <div className="flex flex-col gap-2 bg-white/5 p-3 rounded-xl">
              <DragNumberField 
                label="Shift All Subtitles" 
                value={shiftOffset} 
                onChange={setShiftOffset} 
                className="w-full"
              />
              <PillButton 
                variant="outline" 
                onClick={applyTimeShift}
                disabled={shiftOffset === 0 || subtitles.length === 0}
                icon={<span className="material-symbols-outlined text-[16px]">history</span>}
              >
                Apply Global Offset
              </PillButton>
              <p className="text-[10px] text-white/30 px-1 leading-relaxed">
                Tip: If subtitles appear too late, shift negative (e.g. -0.5s).
              </p>
            </div>
          </div>

          <div className="flex flex-col gap-3">
            <SectionLabel>Typography</SectionLabel>
            <div className="flex flex-col gap-1.5">
              <SearchableDropdown 
                label="Font Family" 
                value={style.font} 
                options={FONT_OPTIONS}
                onChange={(v) => setStyle(s => ({ ...s, font: v }))} 
              />
              <div className="flex gap-1 h-[49px]">
                <FieldDropdown 
                  label="Weight" 
                  value={style.fontWeight} 
                  options={['Regular', 'Bold', 'Black']}
                  onChange={(v) => setStyle(s => ({ ...s, fontWeight: v }))} 
                  className="flex-1"
                />
                <div className="flex-1 border border-[#595959] rounded-xl flex flex-col justify-center px-2.5 pb-2 pt-[5px]">
                  <p className="text-[11px] font-medium text-white/30 tracking-[0.1px]">Size</p>
                  <input 
                    type="number" 
                    value={style.fontSize} 
                    onChange={(e) => setStyle(s => ({ ...s, fontSize: parseInt(e.target.value) || 12 }))}
                    className="bg-transparent text-[11px] font-medium text-white outline-none w-full"
                  />
                </div>
              </div>
            </div>
          </div>

          <div className="flex flex-col gap-3">
            <SectionLabel>Visual Style</SectionLabel>
            <div className="flex flex-col gap-1 bg-white/5 p-3 rounded-xl">
              <RangeSlider 
                label="Position (Y)" 
                value={style.positionY} 
                min={0} max={100} 
                formatValue={v => `${v}%`}
                onChange={(v) => setStyle(s => ({ ...s, positionY: v }))} 
              />
              <RangeSlider 
                label="Outline" 
                value={style.strokeWidth} 
                min={0} max={10} step={0.5}
                formatValue={v => `${v}px`}
                onChange={(v) => setStyle(s => ({ ...s, strokeWidth: v }))} 
              />

              <div className="flex items-center justify-between px-2 py-2 select-none">
                <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">Background Transparency</span>
                <button 
                  onClick={() => setStyle(s => ({ ...s, backgroundOpacity: s.backgroundOpacity === 0 ? 0.5 : 0 }))}
                  className={`w-10 h-5 rounded-full transition-colors relative ${style.backgroundOpacity > 0 ? 'bg-[#969696]' : 'bg-white/10'}`}
                >
                  <div className={`absolute top-1 w-3 h-3 rounded-full bg-white transition-all ${style.backgroundOpacity > 0 ? 'right-1' : 'left-1'}`} />
                </button>
              </div>

              {style.backgroundOpacity > 0 && (
                <RangeSlider 
                  label="BG Opacity" 
                  value={style.backgroundOpacity} 
                  min={0.1} max={1} step={0.1}
                  onChange={(v) => setStyle(s => ({ ...s, backgroundOpacity: v }))} 
                />
              )}

              <div className="grid grid-cols-3 gap-2 mt-2">
                <div className="flex flex-col gap-1">
                  <span className="text-[10px] text-white/30 px-1 truncate">Text</span>
                  <input type="color" value={style.color} onChange={(e) => setStyle(s => ({ ...s, color: e.target.value }))} className="w-full h-8 bg-transparent border border-[#595959] rounded-lg cursor-pointer" />
                </div>
                <div className="flex flex-col gap-1">
                  <span className="text-[10px] text-white/30 px-1 truncate">BG</span>
                  <input type="color" value={style.backgroundColor} onChange={(e) => setStyle(s => ({ ...s, backgroundColor: e.target.value }))} className="w-full h-8 bg-transparent border border-[#595959] rounded-lg cursor-pointer" />
                </div>
                <div className="flex flex-col gap-1">
                  <span className="text-[10px] text-white/30 px-1 truncate">Stroke</span>
                  <input type="color" value={style.strokeColor} onChange={(e) => setStyle(s => ({ ...s, strokeColor: e.target.value }))} className="w-full h-8 bg-transparent border border-[#595959] rounded-lg cursor-pointer" />
                </div>
              </div>
            </div>
          </div>

          {error && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-xl text-red-400 text-[11px]">
              {error}
            </div>
          )}
        </div>

        <div className="flex flex-col gap-2 pt-4 border-t border-white/5">
          {isExporting && (
            <div className="flex flex-col gap-1 px-2 mb-2">
              <div className="flex justify-between text-[10px] text-white/60">
                <span>Baking subtitles...</span>
                <span>{Math.round(progress * 100)}%</span>
              </div>
              <div className="h-1 bg-white/10 rounded-full overflow-hidden">
                <div className="h-full bg-[#969696] transition-all" style={{ width: `${progress * 100}%` }} />
              </div>
            </div>
          )}

          <PillButton 
            variant="outline" 
            onClick={handleExportSRT}
            disabled={subtitles.length === 0}
            icon={<span className="material-symbols-outlined text-[18px]">description</span>}
          >
            Download .SRT
          </PillButton>
          <PillButton 
            variant="solid" 
            onClick={handleBurnInExport}
            disabled={!media || subtitles.length === 0 || isExporting}
            icon={isExporting ? <span className="animate-spin material-symbols-outlined text-[18px]">sync</span> : <span className="material-symbols-outlined text-[18px]">download</span>}
          >
            {isExporting ? 'Exporting...' : 'Export & Save Video'}
          </PillButton>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';

interface SearchableDropdownProps {
  label: string;
  value: string;
  options: string[];
  onChange: (val: string) => void;
  className?: string;
  placeholder?: string;
}

export const SearchableDropdown: React.FC<SearchableDropdownProps> = ({
  label,
  value,
  options,
  onChange,
  className = '',
  placeholder = 'Search fonts...'
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const ref = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (ref.current && !ref.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isOpen && inputRef.current) {
      inputRef.current.focus();
    }
    if (!isOpen) {
      setSearch('');
    }
  }, [isOpen]);

  const filteredOptions = options.filter(opt => 
    opt.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div ref={ref} className={`relative ${className}`}>
      <button 
        type="button" 
        onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none focus:outline-none"
      >
        <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white tracking-[0.1px] truncate pr-2">{value}</span>
          <span className={`material-symbols-outlined text-[16px] text-[rgba(218,220,224,0.5)] mr-1 transition-transform ${isOpen ? 'rotate-180' : ''}`}>keyboard_arrow_down</span>
        </div>
      </button>

      {isOpen && (
        <div className="absolute z-50 top-[calc(100%+4px)] left-0 w-full bg-[#0e0e0e] border border-[#595959] rounded-xl overflow-hidden shadow-xl backdrop-blur-md animate-dropdown origin-top flex flex-col">
          <div className="p-2 border-b border-[#595959]/30">
            <div className="flex items-center gap-2 bg-white/5 rounded-lg px-2 py-1">
              <span className="material-symbols-outlined text-[16px] text-white/40">search</span>
              <input
                ref={inputRef}
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder={placeholder}
                className="bg-transparent text-[11px] text-white outline-none w-full py-1"
                onClick={(e) => e.stopPropagation()}
              />
            </div>
          </div>
          <div className="max-h-48 overflow-y-auto dark-scrollbar py-1">
            {filteredOptions.length > 0 ? (
              filteredOptions.map((opt) => (
                <button 
                  key={opt} 
                  type="button"
                  className={`w-full text-left px-3 py-2 text-[11px] font-medium tracking-[0.1px] hover:bg-[#1a1a1a] transition-colors flex items-center justify-between ${value === opt ? 'bg-[#1a1a1a] text-white' : 'text-[rgba(218,220,224,0.9)]'}`}
                  onClick={() => { onChange(opt); setIsOpen(false); }}
                >
                  <span style={{ fontFamily: opt }}>{opt}</span>
                  {value === opt && <span className="material-symbols-outlined text-[14px]">check</span>}
                </button>
              ))
            ) : (
              <div className="px-3 py-4 text-[10px] text-white/40 text-center">No fonts found</div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};
